/** Inert source-bound producer controls. They never execute Docker or manufacture actual evidence. */
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
import {derivative,harnessPin} from './factory.mjs';
const root='.artifacts/p05-topic-restore',rows=[];
async function check(id,work){try{await work();rows.push({id,status:'PASS'});}catch(error){rows.push({id,status:'FAIL',message:error.message});}}
const source=name=>readFileSync(root+'/'+name,'utf8'),tree=name=>ts.createSourceFile(name,source(name),ts.ScriptTarget.Latest,true,ts.ScriptKind.JS);
const fn=(name,method)=>{const t=tree(name);return t.statements.find(n=>ts.isFunctionDeclaration(n)&&n.name?.text===method).getText(t).replace(/^export /,'');};
await check('exact_finite_harness_derivative_and_all_real_imports',()=>{const raw=readFileSync('tests/p05-topic-lifecycle/harness.mjs'),d=derivative(raw);assert.equal(d.proof.original_sha256,harnessPin);assert.equal(d.proof.semantic_replacements.length,7);assert.equal(d.proof.auth_or_grant_substitution,false);for(const n of ['Rooms','TopicGames','TopicRoomRegistry','TopicRoomLifecycle','PrivateTopicPreferences','createApp'])assert(d.text.includes(n));assert(d.text.includes('async function close(){await app?.close();await pool.end();}'));assert(!d.text.includes('rmSync(path,{recursive:true,force:true})'));assert.throws(()=>derivative(Buffer.from(raw.toString()+'\n')));});
for(const flaw of ['none','worldreadable','symlink','otheruid','outsideprivate','wrongkeys','wrongphase','backwardsfloor'])await check('config_'+flaw,()=>{const privateRoot='/tmp/venus-topic-restore-private-abcd',config={privateRoot,directory:privateRoot+'/authority',keyringFile:privateRoot+'/keyring.json',stateFile:privateRoot+'/state.json',phase:1,now:1000000};if(flaw==='outsideprivate')config.privateRoot='/tmp/unowned';if(flaw==='wrongkeys')config.keyringFile='/etc/keys';if(flaw==='wrongphase')config.phase=4;if(flaw==='backwardsfloor')config.now=999999;const stat={isFile:()=>true,isSymbolicLink:()=>flaw==='symlink',mode:flaw==='worldreadable'?0o644:0o600,uid:flaw==='otheruid'?2000:1000},context=vm.createContext({assert,process:{platform:'linux',env:{VENUS_P05_ISOLATED_FIXTURE:'1'},getuid:()=>1000},resolve:x=>x,dirname:x=>x.slice(0,x.lastIndexOf('/')),join:(...x)=>x.join('/'),lstatSync:()=>stat,readFileSync:()=>JSON.stringify(config)}),run=vm.runInContext('('+fn('factory.mjs','checkedPrivateConfig')+')',context);let success=false;try{run(privateRoot+'/phase1.json');success=true;}catch{}assert.equal(success,flaw==='none');});
await check('all_user_rows_sequences_compare_rejects_partial_restore',()=>{const run=vm.runInNewContext('('+fn('observations.mjs','assertRestored')+')',{assert}),a={privateRows:{'public.rooms':['old encrypted data'],'public.room_sessions':['old credential']},privateSequences:[{last_value:'2'}],summary:[],comparison_scope:'test'};assert(run(a,structuredClone(a)).all_user_rows_equal);for(const defect of ['missingtable','changedcipher','changedsequence']){const b=structuredClone(a);if(defect==='missingtable')delete b.privateRows['public.room_sessions'];if(defect==='changedcipher')b.privateRows['public.rooms']=['new encrypted data'];if(defect==='changedsequence')b.privateSequences[0].last_value='3';assert.throws(()=>run(a,b));}});
const actors=['actor1','actor2'],fixture={room:'roomD',game:'gameD'};
function liveData(){return {stored:{game:{state:'active',snapshot_cipher:'cipher'},data:{state:'active',plan:{actors,interaction:'pair_private'},invitation:{state:'active',acks:[...actors],active_until:1200000},action:{state:'active',acks:[...actors],active_until:1200000},conversation_id:'conv',clock_floor:1000000,boot_id:'old'},history:{history:['old']}},conversation:{state:{state:'open',epoch:1,parent_expires_at:1200000,clock_floor:1000000,offer:{state:'active',acks:[...actors],expires_at:1200000},advice:[{state:'accepted',text:'synthetic',expires_at:1200000}]}},chat:{epoch:1,messages:[{text:'synthetic'}]},sessions:actors.map(member_id=>({member_id,revoked_at:null,removed_at:null,expires_at:new Date(2000000)})),refs:4};}
for(const defect of ['none','naturalexpiry','clockfloorfuture','missingactionack','pendingadvice','emptychat','revokedcredential','norefs'])await check('untouched_D_rejects_confounded_control_'+defect,async()=>{const data=liveData();if(defect==='naturalexpiry')data.stored.data.invitation.active_until=1002000;if(defect==='clockfloorfuture')data.conversation.state.clock_floor=1003000;if(defect==='missingactionack')data.stored.data.action.acks.pop();if(defect==='pendingadvice')data.conversation.state.advice[0].state='pending';if(defect==='emptychat')data.chat.messages=[];if(defect==='revokedcredential')data.sessions[0].revoked_at=new Date();if(defect==='norefs')data.refs=0;const run=vm.runInNewContext('('+fn('observations.mjs','liveUntouched')+')',{assert,storedGame:async()=>data.stored,loadTopicObject:async(_p,_k,scope)=>scope.kind==='conversation'?data.conversation:data.chat,sha:JSON.stringify}),pool={query:async sql=>({rows:sql.includes('FROM room_sessions')?data.sessions:[{n:data.refs}]})};let accepted=false;try{await run(pool,{},fixture,1002000);accepted=true;}catch{}assert.equal(accepted,defect==='none');});
for(const defect of ['none','notstopped','acksremain','objectsremain','refsremain','snapshotchanged','historychanged'])await check('raw_boot_observer_rejects_residual_grant_'+defect,async()=>{const data=liveData();data.stored.data.state='stopped';for(const name of ['invitation','action']){data.stored.data[name].state='stopped';data.stored.data[name].acks=[];}const before={snapshot_sha256:JSON.stringify(data.stored.game.snapshot_cipher),history_sha256:JSON.stringify(data.stored.history)};if(defect==='notstopped')data.stored.data.state='active';if(defect==='acksremain')data.stored.data.action.acks=['actor1'];if(defect==='snapshotchanged')data.stored.game.snapshot_cipher='changed';if(defect==='historychanged')data.stored.history={history:[]};const run=vm.runInNewContext('('+fn('observations.mjs','revokedUntouched')+')',{assert,storedGame:async()=>data.stored,sha:JSON.stringify}),pool={query:async sql=>({rows:[{n:sql.includes('FROM topic_game_objects')?(defect==='objectsremain'?1:0):(defect==='refsremain'?1:0)}]})};let accepted=false;try{await run(pool,{},fixture,before);accepted=true;}catch{}assert.equal(accepted,defect==='none');});
await check('actual_child_order_boot_rawobserver_before_reconcile_maintain_listen',()=>{const s=source('child.mjs'),calls=['await h.topics.bootGate()','await revokedUntouched(','await h.legacy.reconcilePublicPairPolicy()','await h.rooms.maintain()','await h.listen()'];for(let n=1;n<calls.length;n++)assert(s.indexOf(calls[n-1])<s.indexOf(calls[n]));assert(s.includes("if(config.phase>1){assert(state?.D)"));assert(s.includes("await runtime?.close()"));});
await check('fixed14checks_no_missing_or_duplicate_acceptance',()=>{for(const file of ['run.mjs','controller.mjs']){const s=source(file);assert(s.includes('Array.from({length:14}'));assert(s.includes("report.checks.length,14")||s.includes('r.checks.length,14'));assert(s.includes('new Set('));}const ids=[...source('phases.mjs').matchAll(/id:'(P05-RESTORE-\d\d)'/g)].map(m=>m[1]);assert.equal(new Set(ids).size,10);for(const n of [3,6,7,14])assert(source('controller.mjs').includes("check('P05-RESTORE-"+String(n).padStart(2,'0')+"'"));});
await check('dump_restore_are_actual_full_database_and_quiescent',()=>{const s=source('run.mjs');for(const required of ["'pg_dump','--format=custom','--no-owner','--no-acl'","'pg_restore','--clean','--if-exists','--no-owner','--no-acl','--single-transaction'",'pg_stat_activity',"await quiescent('before-dump')","await quiescent('before-restore')"])assert(s.includes(required),required);assert(!s.includes('--table'));assert(!s.includes('INSERT INTO'));const c=source('controller.mjs');assert(c.includes("assert(pool===null&&child===null"));assert(c.includes("await pool.end();pool=null"));assert(c.includes("await waitSignal('RESTORE_COMPLETE')"));assert(c.indexOf('assertRestored(baseline,actual)')<c.indexOf("await boot(3)"));});
await check('external_roots_plus_legacy_deletion_ledger_and_untouched_D',()=>{assert(source('observations.mjs').includes("[...rootNames,'deletions']"));const c=source('controller.mjs');assert(c.includes("assert.deepEqual(restoredRoots,afterRoots"));assert(c.includes('assert.deepEqual(roomAuthority(restoredRoots,original.D.room),original.authorityDAtDump)'));assert(source('phases.mjs').includes('roomAuthority(after,state.D.room)'));});
await check('three_real_child_processes_and_no_stdout_secrets',()=>{const c=source('controller.mjs');assert(c.includes("fork(resolve('tests/p05-topic-restore/child.mjs')"));assert(c.includes("c.once('exit'"));assert(c.includes('completed.runtime_cleanup===\'completed\''));assert(c.includes("s.hash.digest('hex')"));assert(!c.includes("streams[name].push"));assert(c.includes('new Set(report.children.map(v=>v.pid)).size,3'));});
await check('runtime_and_final_source_producer_cleanup_fail_closed',()=>{const s=source('run.mjs');for(const required of ['assert.deepEqual(mid.files,before.files)','assert.deepEqual(pinsMid,pinsBefore)','assert(mid&&pinsMid&&runtimeUnchanged)','assert.deepEqual(final.files,before.files)','assert.deepEqual(pinsFinal,pinsBefore)',"if(failure||cleanup!=='PASS'||!unchanged)status='FAIL'","r.runtime_cleanup,'completed'"])assert(s.includes(required),required);assert(s.indexOf('inputs-after-finally.json')>s.indexOf("cleanup='PASS'"));});
await check('binding_pending_deliberately_refuses_unreviewed_runtime',()=>{const b=JSON.parse(source('BINDING.json'));assert.equal(b.root_run_ack,false);assert.equal(b.source_identity,null);const r=source('run.mjs');assert(r.indexOf("assert.equal(binding.status,'ROOT_FROZEN_BINDING_REVIEWED')")<r.indexOf('const project='));});
const report={schema_version:1,role:'AUTHOR_NOT_ACCEPTOR',scope:'INERT_MOCKED_NEGATIVE_OR_AST_CONTROLS_NOT_ACTUAL_RESTORE',rows};writeFileSync(root+'/author-controls-results.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));if(rows.some(r=>r.status!=='PASS'))process.exitCode=1;
